// The package's own code imports the package by its PUBLISHED name
// ("selfref") — Node's PACKAGE_SELF_RESOLVE: the nearest package scope's
// matching "name" answers through its own "exports", regardless of the
// directory it was installed under (here: node_modules/aliased). The
// namespace self-import is the benign self-cycle shape.
import { util } from "selfref/util";
import * as self from "selfref";
self;
export function combined() {
  return "idx+" + util();
}
